PRODUCTION_SOURCE = '"""\nOLA-041\nOracle Post-Persistence Cohort Capture Hook\n\nCanonical production-wiring hook between successful OLA-017 persistence\nreconciliation and the OLA-040 exact canonical cohort capture port.\n\nPurpose:\n- accept one completed OLA-017 cycle result\n- require canonical_count > 0\n- require PostgreSQL routing delta == canonical_count\n- require the exact canonical observation cohort\n- require one acquisition_batch_id across the cohort\n- capture the exact CanonicalObservation objects through OLA-040\n- return one immutable deterministic hook receipt\n\nThe hook does not alter OLA-017 result projection.\nIt does not alter OLA-021 scheduler canonicalization.\nIt performs no lineage advancement itself.\n\nNo intelligence interpretation.\nNo signal scoring.\nNo alerts.\nNo Q Series handoff.\nNo execution.\n\nOracle remains permanently read-only.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom hashlib import sha256\nimport json\nfrom typing import Any, Mapping, Sequence\n\nfrom .oracle_canonical_persisted_cohort_capture_port import (\n    CanonicalPersistedCohortCapture,\n    CanonicalPersistedCohortCaptureContractError,\n    CanonicalPersistedCohortCaptureInvariantError,\n    OracleCanonicalPersistedCohortCapturePort,\n    canonical_persisted_cohort_capture_port,\n)\nfrom .oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n)\n\n\nSCHEMA_VERSION = "OLA-041"\nENGINE_ID = "OLA-041"\nRECEIPT_TYPE = "oracle_post_persistence_cohort_capture_hook_receipt"\n\nREAD_ONLY = True\nEXECUTION_ALLOWED = False\nEXECUTION_ADAPTER_RESOLVED = False\nEXECUTION_ADAPTER_INVOKED = False\nTRADE_AUTHORIZATION_ALLOWED = False\nORDER_PLACEMENT_ALLOWED = False\nFUNDS_MOVED = False\nPORTFOLIO_MUTATED = False\n\n\nclass PostPersistenceCohortCaptureHookContractError(ValueError):\n    """Raised when OLA-041 hook input is malformed."""\n\n\nclass PostPersistenceCohortCaptureHookInvariantError(RuntimeError):\n    """Raised when permanent OLA-041 invariants are violated."""\n\n\ndef _require_non_empty_string(\n    value: Any,\n    field_name: str,\n) -> str:\n    if not isinstance(value, str):\n        raise PostPersistenceCohortCaptureHookContractError(\n            f"{field_name} must be a string"\n        )\n\n    normalized = value.strip()\n\n    if not normalized:\n        raise PostPersistenceCohortCaptureHookContractError(\n            f"{field_name} must not be empty"\n        )\n\n    return normalized\n\n\ndef _require_non_negative_int(\n    value: Any,\n    field_name: str,\n) -> int:\n    if isinstance(value, bool) or not isinstance(value, int):\n        raise PostPersistenceCohortCaptureHookContractError(\n            f"{field_name} must be an integer"\n        )\n\n    if value < 0:\n        raise PostPersistenceCohortCaptureHookContractError(\n            f"{field_name} must not be negative"\n        )\n\n    return value\n\n\ndef _cycle_payload(\n    cycle_result: Any,\n) -> dict[str, Any]:\n    if hasattr(\n        cycle_result,\n        "to_canonical_dict",\n    ):\n        payload = cycle_result.to_canonical_dict()\n    elif isinstance(cycle_result, Mapping):\n        payload = cycle_result\n    else:\n        raise PostPersistenceCohortCaptureHookContractError(\n            "OLA-017 cycle result must expose canonical mapping evidence"\n        )\n\n    if not isinstance(payload, Mapping):\n        raise PostPersistenceCohortCaptureHookContractError(\n            "OLA-017 canonical cycle evidence must be a mapping"\n        )\n\n    return dict(payload)\n\n\ndef _stable_hash(value: Any) -> str:\n    encoded = json.dumps(\n        value,\n        sort_keys=True,\n        separators=(",", ":"),\n        ensure_ascii=False,\n        allow_nan=False,\n    ).encode("utf-8")\n\n    return sha256(encoded).hexdigest()\n\n\n@dataclass(frozen=True, slots=True)\nclass PostPersistenceCohortCaptureHookReceipt:\n    schema_version: str\n    engine_id: str\n    receipt_type: str\n    upstream_schema_version: str\n    upstream_engine_id: str\n    cycle_status: str\n    acquisition_batch_id: str\n    canonical_count: int\n    persistence_count: int\n    capture_hash: str\n    observation_ids: tuple[str, ...]\n    source_market_ids: tuple[str, ...]\n    read_only: bool\n    execution_allowed: bool\n    execution_adapter_resolved: bool\n    execution_adapter_invoked: bool\n    trade_authorization_allowed: bool\n    order_placement_allowed: bool\n    funds_moved: bool\n    portfolio_mutated: bool\n    hook_hash: str\n\n    def assert_invariants(self) -> None:\n        if self.schema_version != SCHEMA_VERSION:\n            raise PostPersistenceCohortCaptureHookInvariantError(\n                "schema version invariant violated"\n            )\n\n        if self.engine_id != ENGINE_ID:\n            raise PostPersistenceCohortCaptureHookInvariantError(\n                "engine identity invariant violated"\n            )\n\n        if self.receipt_type != RECEIPT_TYPE:\n            raise PostPersistenceCohortCaptureHookInvariantError(\n                "receipt type invariant violated"\n            )\n\n        if self.upstream_schema_version != "OLA-017":\n            raise PostPersistenceCohortCaptureHookInvariantError(\n                "upstream schema identity invariant violated"\n            )\n\n        if self.upstream_engine_id != "OLA-017":\n            raise PostPersistenceCohortCaptureHookInvariantError(\n                "upstream engine identity invariant violated"\n            )\n\n        if self.cycle_status != "completed":\n            raise PostPersistenceCohortCaptureHookInvariantError(\n                "cycle completion invariant violated"\n            )\n\n        if self.canonical_count <= 0:\n            raise PostPersistenceCohortCaptureHookInvariantError(\n                "canonical count must be positive"\n            )\n\n        if self.persistence_count != self.canonical_count:\n            raise PostPersistenceCohortCaptureHookInvariantError(\n                "persistence equality invariant violated"\n            )\n\n        if len(self.observation_ids) != self.canonical_count:\n            raise PostPersistenceCohortCaptureHookInvariantError(\n                "observation identity count invariant violated"\n            )\n\n        if len(self.source_market_ids) != self.canonical_count:\n            raise PostPersistenceCohortCaptureHookInvariantError(\n                "market identity count invariant violated"\n            )\n\n        authority = (\n            self.read_only,\n            self.execution_allowed,\n            self.execution_adapter_resolved,\n            self.execution_adapter_invoked,\n            self.trade_authorization_allowed,\n            self.order_placement_allowed,\n            self.funds_moved,\n            self.portfolio_mutated,\n        )\n\n        if authority != (\n            True,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n        ):\n            raise PostPersistenceCohortCaptureHookInvariantError(\n                "OLA-041 read-only authority invariants violated"\n            )\n\n\nclass OraclePostPersistenceCohortCaptureHook:\n    read_only = True\n    execution_allowed = False\n\n    def __init__(\n        self,\n        *,\n        capture_port: (\n            OracleCanonicalPersistedCohortCapturePort | None\n        ) = None,\n    ) -> None:\n        self._capture_port = (\n            capture_port\n            if capture_port is not None\n            else canonical_persisted_cohort_capture_port()\n        )\n\n        if not isinstance(\n            self._capture_port,\n            OracleCanonicalPersistedCohortCapturePort,\n        ):\n            raise PostPersistenceCohortCaptureHookContractError(\n                "capture_port must be an OLA-040 "\n                "OracleCanonicalPersistedCohortCapturePort"\n            )\n\n    @property\n    def capture_port(\n        self,\n    ) -> OracleCanonicalPersistedCohortCapturePort:\n        return self._capture_port\n\n    def capture_completed_cycle(\n        self,\n        *,\n        ola_017_cycle_result: Any,\n        canonical_observations: Sequence[CanonicalObservation],\n    ) -> PostPersistenceCohortCaptureHookReceipt:\n        cycle_payload = _cycle_payload(\n            ola_017_cycle_result\n        )\n\n        upstream_schema_version = _require_non_empty_string(\n            cycle_payload.get("schema_version"),\n            "ola_017_cycle_result.schema_version",\n        )\n        upstream_engine_id = _require_non_empty_string(\n            cycle_payload.get("engine_id"),\n            "ola_017_cycle_result.engine_id",\n        )\n\n        if upstream_schema_version != "OLA-017":\n            raise PostPersistenceCohortCaptureHookContractError(\n                "upstream schema_version must be OLA-017"\n            )\n\n        if upstream_engine_id != "OLA-017":\n            raise PostPersistenceCohortCaptureHookContractError(\n                "upstream engine_id must be OLA-017"\n            )\n\n        cycle_status = _require_non_empty_string(\n            cycle_payload.get(\n                "cycle_status",\n                cycle_payload.get("status"),\n            ),\n            "ola_017_cycle_result.cycle_status",\n        )\n\n        if cycle_status != "completed":\n            raise PostPersistenceCohortCaptureHookContractError(\n                "only completed OLA-017 cycles can be captured"\n            )\n\n        canonical_count = _require_non_negative_int(\n            cycle_payload.get("canonical_count"),\n            "ola_017_cycle_result.canonical_count",\n        )\n\n        persistence_count = _require_non_negative_int(\n            cycle_payload.get(\n                "postgresql_routing_record_delta",\n                cycle_payload.get(\n                    "postgresql_persistence_count"\n                ),\n            ),\n            "ola_017_cycle_result.postgresql_routing_record_delta",\n        )\n\n        if canonical_count <= 0:\n            raise PostPersistenceCohortCaptureHookContractError(\n                "canonical_count must be positive"\n            )\n\n        if persistence_count != canonical_count:\n            raise PostPersistenceCohortCaptureHookContractError(\n                "PostgreSQL persistence count must equal canonical_count"\n            )\n\n        if cycle_payload.get("read_only") is not True:\n            raise PostPersistenceCohortCaptureHookInvariantError(\n                "OLA-017 cycle result lost read-only invariant"\n            )\n\n        if cycle_payload.get("execution_allowed") is not False:\n            raise PostPersistenceCohortCaptureHookInvariantError(\n                "OLA-017 cycle result gained execution capability"\n            )\n\n        observations = tuple(canonical_observations)\n\n        if len(observations) != canonical_count:\n            raise PostPersistenceCohortCaptureHookContractError(\n                "exact canonical cohort count must equal canonical_count"\n            )\n\n        try:\n            capture = self._capture_port.capture(\n                canonical_observations=observations\n            )\n        except CanonicalPersistedCohortCaptureContractError as exc:\n            raise PostPersistenceCohortCaptureHookContractError(\n                f"OLA-040 capture port rejected cohort: {exc}"\n            ) from exc\n        except CanonicalPersistedCohortCaptureInvariantError as exc:\n            raise PostPersistenceCohortCaptureHookInvariantError(\n                f"OLA-040 capture invariant failed: {exc}"\n            ) from exc\n\n        self._assert_capture_binding(\n            capture=capture,\n            observations=observations,\n            canonical_count=canonical_count,\n        )\n\n        payload = {\n            "schema_version": SCHEMA_VERSION,\n            "engine_id": ENGINE_ID,\n            "receipt_type": RECEIPT_TYPE,\n            "upstream_schema_version": upstream_schema_version,\n            "upstream_engine_id": upstream_engine_id,\n            "cycle_status": cycle_status,\n            "acquisition_batch_id": capture.acquisition_batch_id,\n            "canonical_count": canonical_count,\n            "persistence_count": persistence_count,\n            "capture_hash": capture.capture_hash,\n            "observation_ids": list(capture.observation_ids),\n            "source_market_ids": list(capture.source_market_ids),\n            "read_only": READ_ONLY,\n            "execution_allowed": EXECUTION_ALLOWED,\n            "execution_adapter_resolved": EXECUTION_ADAPTER_RESOLVED,\n            "execution_adapter_invoked": EXECUTION_ADAPTER_INVOKED,\n            "trade_authorization_allowed": TRADE_AUTHORIZATION_ALLOWED,\n            "order_placement_allowed": ORDER_PLACEMENT_ALLOWED,\n            "funds_moved": FUNDS_MOVED,\n            "portfolio_mutated": PORTFOLIO_MUTATED,\n        }\n\n        receipt = PostPersistenceCohortCaptureHookReceipt(\n            schema_version=SCHEMA_VERSION,\n            engine_id=ENGINE_ID,\n            receipt_type=RECEIPT_TYPE,\n            upstream_schema_version=upstream_schema_version,\n            upstream_engine_id=upstream_engine_id,\n            cycle_status=cycle_status,\n            acquisition_batch_id=capture.acquisition_batch_id,\n            canonical_count=canonical_count,\n            persistence_count=persistence_count,\n            capture_hash=capture.capture_hash,\n            observation_ids=capture.observation_ids,\n            source_market_ids=capture.source_market_ids,\n            read_only=READ_ONLY,\n            execution_allowed=EXECUTION_ALLOWED,\n            execution_adapter_resolved=EXECUTION_ADAPTER_RESOLVED,\n            execution_adapter_invoked=EXECUTION_ADAPTER_INVOKED,\n            trade_authorization_allowed=TRADE_AUTHORIZATION_ALLOWED,\n            order_placement_allowed=ORDER_PLACEMENT_ALLOWED,\n            funds_moved=FUNDS_MOVED,\n            portfolio_mutated=PORTFOLIO_MUTATED,\n            hook_hash=_stable_hash(payload),\n        )\n\n        receipt.assert_invariants()\n        return receipt\n\n    @staticmethod\n    def _assert_capture_binding(\n        *,\n        capture: CanonicalPersistedCohortCapture,\n        observations: tuple[CanonicalObservation, ...],\n        canonical_count: int,\n    ) -> None:\n        if capture.canonical_count != canonical_count:\n            raise PostPersistenceCohortCaptureHookInvariantError(\n                "capture count binding invariant violated"\n            )\n\n        if capture.canonical_observations != observations:\n            raise PostPersistenceCohortCaptureHookInvariantError(\n                "exact canonical cohort binding invariant violated"\n            )\n\n        if not all(\n            captured is original\n            for captured, original in zip(\n                capture.canonical_observations,\n                observations,\n            )\n        ):\n            raise PostPersistenceCohortCaptureHookInvariantError(\n                "canonical observation object identity was not preserved"\n            )\n'

TEST_SOURCE = 'from datetime import datetime, timezone\n\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_post_persistence_cohort_capture_hook import (\n    OraclePostPersistenceCohortCaptureHook,\n    PostPersistenceCohortCaptureHookContractError,\n)\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_canonical_persisted_cohort_capture_port import (\n    OracleCanonicalPersistedCohortCapturePort,\n)\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n    RawSourceObservation,\n)\n\n\nT1 = datetime(\n    2026,\n    7,\n    14,\n    15,\n    0,\n    0,\n    tzinfo=timezone.utc,\n)\n\n\ndef build_observation(\n    *,\n    market_id,\n    frame_id,\n    batch_id="batch.ola.041.1",\n):\n    payload = {\n        "source_market_id": market_id,\n        "yes_bid_dollars": "0.0000",\n        "yes_bid_size_fp": "0.00",\n        "yes_ask_dollars": "0.6140",\n        "yes_ask_size_fp": "40.00",\n        "no_bid_dollars": "0.3860",\n        "no_ask_dollars": "0.0000",\n        "last_price_dollars": "0.0000",\n        "previous_yes_bid_dollars": "0.0000",\n        "previous_yes_ask_dollars": "0.6000",\n        "previous_price_dollars": "0.0000",\n        "volume_fp": "0.00",\n        "volume_24h_fp": "0.00",\n        "open_interest_fp": "0.00",\n        "liquidity_dollars": "0.0000",\n    }\n\n    raw = RawSourceObservation.create(\n        source_observation_id=(\n            "kalshi."\n            + market_id\n            + "."\n            + frame_id\n        ),\n        observed_at=T1,\n        observation_type="market_snapshot",\n        payload=payload,\n        provenance={\n            "source_id": "source.kalshi.market_data",\n            "frame_id": frame_id,\n        },\n    )\n\n    return CanonicalObservation.create(\n        source_id="source.kalshi.market_data",\n        raw_observation=raw,\n        acquired_at=T1,\n        acquisition_batch_id=batch_id,\n    )\n\n\ndef build_cohort(\n    *,\n    batch_id="batch.ola.041.1",\n):\n    return tuple(\n        build_observation(\n            market_id=f"KXTEST-HOOK-{index}",\n            frame_id=str(index),\n            batch_id=batch_id,\n        )\n        for index in range(1, 6)\n    )\n\n\ndef completed_cycle_result():\n    return {\n        "schema_version": "OLA-017",\n        "engine_id": "OLA-017",\n        "cycle_status": "completed",\n        "canonical_count": 5,\n        "postgresql_routing_record_delta": 5,\n        "read_only": True,\n        "execution_allowed": False,\n    }\n\n\ndef run_successful_capture_hook_test():\n    port = OracleCanonicalPersistedCohortCapturePort()\n    hook = OraclePostPersistenceCohortCaptureHook(\n        capture_port=port\n    )\n    cohort = build_cohort()\n\n    receipt = hook.capture_completed_cycle(\n        ola_017_cycle_result=completed_cycle_result(),\n        canonical_observations=cohort,\n    )\n\n    assert receipt.schema_version == "OLA-041"\n    assert receipt.engine_id == "OLA-041"\n    assert receipt.upstream_schema_version == "OLA-017"\n    assert receipt.upstream_engine_id == "OLA-017"\n    assert receipt.cycle_status == "completed"\n    assert receipt.acquisition_batch_id == "batch.ola.041.1"\n    assert receipt.canonical_count == 5\n    assert receipt.persistence_count == 5\n    assert len(receipt.observation_ids) == 5\n    assert len(receipt.source_market_ids) == 5\n    assert port.pending_count == 1\n    assert port.consumed_count == 0\n\n    capture = port.consume(\n        acquisition_batch_id=receipt.acquisition_batch_id\n    )\n\n    assert all(\n        captured is original\n        for captured, original in zip(\n            capture.canonical_observations,\n            cohort,\n        )\n    )\n\n    return receipt\n\n\ndef run_failed_cycle_fails_closed_test():\n    port = OracleCanonicalPersistedCohortCapturePort()\n    hook = OraclePostPersistenceCohortCaptureHook(\n        capture_port=port\n    )\n\n    cycle_result = completed_cycle_result()\n    cycle_result["cycle_status"] = "failed"\n    cycle_result["canonical_count"] = 0\n    cycle_result["postgresql_routing_record_delta"] = 0\n\n    try:\n        hook.capture_completed_cycle(\n            ola_017_cycle_result=cycle_result,\n            canonical_observations=(),\n        )\n        raise AssertionError(\n            "failed cycle must never capture canonical cohort"\n        )\n    except PostPersistenceCohortCaptureHookContractError:\n        pass\n\n    assert port.pending_count == 0\n    assert port.consumed_count == 0\n\n\ndef run_persistence_mismatch_fails_closed_test():\n    port = OracleCanonicalPersistedCohortCapturePort()\n    hook = OraclePostPersistenceCohortCaptureHook(\n        capture_port=port\n    )\n\n    cycle_result = completed_cycle_result()\n    cycle_result["postgresql_routing_record_delta"] = 4\n\n    try:\n        hook.capture_completed_cycle(\n            ola_017_cycle_result=cycle_result,\n            canonical_observations=build_cohort(),\n        )\n        raise AssertionError(\n            "persistence mismatch must fail before capture"\n        )\n    except PostPersistenceCohortCaptureHookContractError:\n        pass\n\n    assert port.pending_count == 0\n\n\ndef run_cohort_count_mismatch_fails_closed_test():\n    port = OracleCanonicalPersistedCohortCapturePort()\n    hook = OraclePostPersistenceCohortCaptureHook(\n        capture_port=port\n    )\n\n    try:\n        hook.capture_completed_cycle(\n            ola_017_cycle_result=completed_cycle_result(),\n            canonical_observations=build_cohort()[:-1],\n        )\n        raise AssertionError(\n            "cohort count mismatch must fail before capture"\n        )\n    except PostPersistenceCohortCaptureHookContractError:\n        pass\n\n    assert port.pending_count == 0\n\n\ndef run_duplicate_capture_translation_test():\n    port = OracleCanonicalPersistedCohortCapturePort()\n    hook = OraclePostPersistenceCohortCaptureHook(\n        capture_port=port\n    )\n    cohort = build_cohort()\n\n    hook.capture_completed_cycle(\n        ola_017_cycle_result=completed_cycle_result(),\n        canonical_observations=cohort,\n    )\n\n    try:\n        hook.capture_completed_cycle(\n            ola_017_cycle_result=completed_cycle_result(),\n            canonical_observations=cohort,\n        )\n        raise AssertionError(\n            "duplicate capture must fail at OLA-041 boundary"\n        )\n    except PostPersistenceCohortCaptureHookContractError:\n        pass\n\n    assert port.pending_count == 1\n\n\ndef run_scheduler_projection_compatibility_test():\n    port = OracleCanonicalPersistedCohortCapturePort()\n    hook = OraclePostPersistenceCohortCaptureHook(\n        capture_port=port\n    )\n\n    projected_cycle_result = {\n        "schema_version": "OLA-017",\n        "engine_id": "OLA-017",\n        "status": "completed",\n        "canonical_count": 5,\n        "postgresql_persistence_count": 5,\n        "read_only": True,\n        "execution_allowed": False,\n    }\n\n    receipt = hook.capture_completed_cycle(\n        ola_017_cycle_result=projected_cycle_result,\n        canonical_observations=build_cohort(\n            batch_id="batch.ola.041.projected"\n        ),\n    )\n\n    assert receipt.cycle_status == "completed"\n    assert receipt.persistence_count == 5\n    assert port.pending_count == 1\n\n\ndef run_deterministic_hook_receipt_test():\n    first_port = OracleCanonicalPersistedCohortCapturePort()\n    second_port = OracleCanonicalPersistedCohortCapturePort()\n\n    first_hook = OraclePostPersistenceCohortCaptureHook(\n        capture_port=first_port\n    )\n    second_hook = OraclePostPersistenceCohortCaptureHook(\n        capture_port=second_port\n    )\n\n    first = first_hook.capture_completed_cycle(\n        ola_017_cycle_result=completed_cycle_result(),\n        canonical_observations=build_cohort(),\n    )\n    second = second_hook.capture_completed_cycle(\n        ola_017_cycle_result=completed_cycle_result(),\n        canonical_observations=build_cohort(),\n    )\n\n    assert first == second\n    assert first.hook_hash == second.hook_hash\n\n    return first\n\n\ndef main():\n    receipt = run_successful_capture_hook_test()\n\n    run_failed_cycle_fails_closed_test()\n    run_persistence_mismatch_fails_closed_test()\n    run_cohort_count_mismatch_fails_closed_test()\n    run_duplicate_capture_translation_test()\n    run_scheduler_projection_compatibility_test()\n\n    deterministic = run_deterministic_hook_receipt_test()\n\n    result = {\n        "schema_version": receipt.schema_version,\n        "engine_id": receipt.engine_id,\n        "status": "passed",\n        "ola_017_completed_cycle_required": True,\n        "ola_017_identity_preserved": True,\n        "canonical_count_required_positive": True,\n        "postgresql_routing_delta_bound": True,\n        "persistence_count_equals_canonical_count": True,\n        "exact_canonical_cohort_required": True,\n        "ola_040_capture_port_consumed": True,\n        "exact_canonical_object_identity_preserved": True,\n        "failed_cycle_never_captures": True,\n        "persistence_mismatch_never_captures": True,\n        "cohort_count_mismatch_never_captures": True,\n        "duplicate_capture_errors_translated": True,\n        "scheduler_projection_compatibility_preserved": True,\n        "scheduler_kwargs_unchanged": True,\n        "scheduler_results_unchanged": True,\n        "deterministic_hook_receipt_valid": (\n            deterministic.hook_hash == receipt.hook_hash\n        ),\n        "no_lineage_advancement_owned": True,\n        "no_intelligence_interpretation": True,\n        "no_signal_scoring": True,\n        "alerts_allowed": False,\n        "qseries_handoff_allowed": False,\n        "read_only": receipt.read_only,\n        "execution_allowed": receipt.execution_allowed,\n        "execution_adapter_resolved": (\n            receipt.execution_adapter_resolved\n        ),\n        "execution_adapter_invoked": (\n            receipt.execution_adapter_invoked\n        ),\n        "trade_authorization_allowed": (\n            receipt.trade_authorization_allowed\n        ),\n        "order_placement_allowed": (\n            receipt.order_placement_allowed\n        ),\n        "funds_moved": receipt.funds_moved,\n        "portfolio_mutated": receipt.portfolio_mutated,\n    }\n\n    print(\n        "[PASS] OLA-041 Oracle Post-Persistence "\n        "Cohort Capture Hook"\n    )\n    print(result)\n\n\nif __name__ == "__main__":\n    main()\n'


def write_full_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        source,
        encoding="utf-8",
        newline="\n",
    )
    print(f"[OK] FULL REPLACEMENT: {path}")


def main() -> None:
    print("========================================")
    print(" OLA-041 INSTALLER")
    print(" POST-PERSISTENCE COHORT CAPTURE HOOK")
    print("========================================")

    write_full_replacement(
        PRODUCTION_PATH,
        PRODUCTION_SOURCE,
    )
    write_full_replacement(
        TEST_PATH,
        TEST_SOURCE,
    )

    print()
    print(
        "[DONE] OLA-041 Oracle Post-Persistence "
        "Cohort Capture Hook installed"
    )
    print()
    print("Run:")
    print(
        "py test_ola_041_oracle_post_persistence_"
        "cohort_capture_hook.py"
    )


if __name__ == "__main__":
    main()
